import { useSyncExternalStore } from 'react';

// src/hooks/useMediaQuery.ts
var subscribe = (query) => (onStoreChange) => {
  const mql = window.matchMedia(query);
  mql.addEventListener("change", onStoreChange);
  return () => mql.removeEventListener("change", onStoreChange);
};
var useMediaQuery = (query) => useSyncExternalStore(
  subscribe(query),
  () => window.matchMedia(query).matches,
  () => false
);
var BREAKPOINTS = {
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
  "2xl": 1536
};
var useBreakpoint = (breakpoint) => useMediaQuery(`(min-width: ${BREAKPOINTS[breakpoint]}px)`);

export { BREAKPOINTS, useBreakpoint, useMediaQuery };
